private data class Entry(val id:Long,val category:String,val amount:Double,val type:String,val date:String,val created:Long,val note:String)
private data class LedgerRow(val date:String,val category:String,val note:String,val receive:Double?,val expense:Double?,val balance:Double,val opening:Boolean=false)

private class DB(context: Context):SQLiteOpenHelper(context,"myexpenses.db",null,1){
    override fun onCreate(db:SQLiteDatabase){ db.execSQL("CREATE TABLE entries(id INTEGER PRIMARY KEY AUTOINCREMENT, particular TEXT NOT NULL, amount REAL NOT NULL, type TEXT NOT NULL, date TEXT NOT NULL, created_at INTEGER NOT NULL, note TEXT NOT NULL DEFAULT '')"); db.execSQL("CREATE TABLE settings(k TEXT PRIMARY KEY,v TEXT)") }
    override fun onUpgrade(db:SQLiteDatabase,oldVersion:Int,newVersion:Int){}
    fun all(where:String="",args:Array<String> = emptyArray(),order:String="date DESC, created_at DESC"):List<Entry>{
        val c=readableDatabase.query("entries",null,where.ifBlank{null},if(where.isBlank())null else args, null,null,order)
        val out=mutableListOf<Entry>(); c.use{while(it.moveToNext())out+=Entry(it.getLong(0),it.getString(1),it.getDouble(2),it.getString(3),it.getString(4),it.getLong(5),it.getString(6))}; return out
    }
    fun insert(category:String,amount:Double,type:String,date:String,note:String){writableDatabase.execSQL("INSERT INTO entries(particular,amount,type,date,created_at,note) VALUES(?,?,?,?,?,?)",arrayOf(category,amount,type,date,System.currentTimeMillis(),note))}
    fun update(e:Entry){writableDatabase.execSQL("UPDATE entries SET particular=?,amount=?,type=?,date=?,note=? WHERE id=?",arrayOf(e.category,e.amount,e.type,e.date,e.note,e.id))}
    fun delete(id:Long){writableDatabase.delete("entries","id=?",arrayOf(id.toString()))}
    fun clearMonth(prefix:String){writableDatabase.delete("entries","date LIKE ?",arrayOf("$prefix%"))}
    fun categories():List<String>{val c=readableDatabase.query("settings",arrayOf("v"),"k=?",arrayOf("categories"),null,null,null);c.use{if(it.moveToFirst())return it.getString(0).split("|").filter{v->v.isNotBlank()}};return emptyList()}
    fun saveCategories(list:List<String>){writableDatabase.execSQL("INSERT OR REPLACE INTO settings(k,v) VALUES(?,?)",arrayOf("categories",list.joinToString("|")))}
}

class MainActivity:ComponentActivity(){
    private lateinit var db:DB
    private val prefs by lazy{getSharedPreferences("prefs",MODE_PRIVATE)}
    private var pendingAction:String?=null
    private val createFile=registerForActivityResult(ActivityResultContracts.CreateDocument("*/*")){uri->if(uri!=null)pendingAction?.let{doCreate(uri,it)};pendingAction=null}
    private val openFile=registerForActivityResult(ActivityResultContracts.OpenDocument()){uri->if(uri!=null)restore(uri)}
    override fun onCreate(savedInstanceState:Bundle?){super.onCreate(savedInstanceState);db=DB(this);setContent{MyExpensesApp(db,prefs,::saveFile,::restoreFile,::printReport,::printLedger,::exportSummary,::exportLedger,::savePdf)}}
    private fun saveFile(kind:String){pendingAction=kind;val name=when(kind){"backup"->"MyExpenses_Backup-${today()}.json";"summary"->"MyExpenses_Summary.csv";"ledger"->"MyExpenses_Ledger.csv";else->"MyExpenses.pdf"};createFile.launch(name)}
    private fun restoreFile(){openFile.launch(arrayOf("application/json","text/plain","*/*"))}
    private fun doCreate(uri:Uri,kind:String){try{contentResolver.openOutputStream(uri)?.use{out->when(kind){"backup"->out.write(backupJson().toByteArray(Charsets.UTF_8));"summary"->out.write(summaryCsv().toByteArray(Charsets.UTF_8));"ledger"->out.write(ledgerCsv().toByteArray(Charsets.UTF_8));"pdf"->makePdf().writeTo(out)}};toast("File saved successfully")}catch(e:Exception){toast("Could not save file: ${e.message}")}}
    private fun restore(uri:Uri){try{val s=contentResolver.openInputStream(uri)?.bufferedReader()?.readText()?:(throw Exception());val db64=Regex("\\\"database\\\"\\s*:\\s*\\\"([^\\\"]+)\\\"").find(s)?.groupValues?.get(1)?:throw Exception();val bytes=android.util.Base64.decode(db64,android.util.Base64.DEFAULT);val tmp=File(filesDir,"restore.db");tmp.writeBytes(bytes);db.close();getDatabasePath("myexpenses.db").delete();tmp.copyTo(getDatabasePath("myexpenses.db"),true);tmp.delete();toast("Backup restored successfully");recreate()}catch(e:Exception){toast("Invalid backup file")}}
    private fun toast(s:String){Toast.makeText(this,s,Toast.LENGTH_SHORT).show()}
    private fun today()=SimpleDateFormat("yyyy-MM-dd",Locale.US).format(Date())
    private fun month()=today().substring(0,7)
    private fun entries():List<Entry>=db.all()
    private fun opening(date:String):Double{var b=0.0;db.all("date < ?",arrayOf(date),"date ASC, created_at ASC").forEach{b+=if(it.type=="income")it.amount else -it.amount};return b}
    private fun filtered():List<Entry>{val f=filterFrom;val t=filterTo;return db.all(buildString{if(f!=null)append("date >= ? ");if(t!=null){if(isNotEmpty())append("AND ");append("date <= ?")}},listOfNotNull(f,t).toTypedArray(),"date ASC, created_at ASC")}
    private var filterFrom:String?=null;private var filterTo:String?=null
    private fun ledger():List<LedgerRow>{var b=if(filterFrom!=null)opening(filterFrom!!) else 0.0;val rows=mutableListOf(LedgerRow(filterFrom?:"Beginning","Opening Balance","",null,null,b,true));filtered().forEach{if(it.type=="income")b+=it.amount else b-=it.amount;rows+=LedgerRow(it.date,it.category,it.note,if(it.type=="income")it.amount else null,if(it.type=="expense")it.amount else null,b)};return rows}
    private fun money(v:Double)="৳"+String.format(Locale.US,"%,.2f",v)
    private fun backupJson():String{val dbBytes=SQLiteDatabase.openDatabase(getDatabasePath("myexpenses.db").path,null,SQLiteDatabase.OPEN_READONLY).let{it.close();getDatabasePath("myexpenses.db").readBytes()};val b64=android.util.Base64.encodeToString(dbBytes,android.util.Base64.NO_WRAP);return "{\n  \"app\":\"MyExpenses\",\n  \"version\":5,\n  \"savedAt\":\"${Date()}\",\n  \"database\":\"$b64\"\n}"}
    private fun summaryCsv():String{val list=filtered();val map=linkedMapOf<String,DoubleArray>();list.forEach{val x=map.getOrPut(it.category){doubleArrayOf(0.0,0.0)};x[if(it.type=="income")0 else 1]+=it.amount};return buildString{append("Particular,Income,Expense,Net\r\n");var ti=0.0;var te=0.0;map.toSortedMap().forEach{(k,v)->ti+=v[0];te+=v[1];append(csv(k)).append(',').append("%.2f".format(Locale.US,v[0])).append(',').append("%.2f".format(Locale.US,v[1])).append(',').append("%.2f".format(Locale.US,v[0]-v[1])).append("\r\n")};append("TOTAL,%.2f,%.2f,%.2f\r\n".format(Locale.US,ti,te,ti-te))}}
    private fun ledgerCsv():String=buildString{append("Date,Category,Note,Receive,Expense,Balance\r\n");ledger().forEach{append(csv(it.date)).append(',').append(csv(it.category)).append(',').append(csv(it.note)).append(',').append(it.receive?.let{"%.2f".format(Locale.US,it)}?:"").append(',').append(it.expense?.let{"%.2f".format(Locale.US,it)}?:"").append(',').append("%.2f".format(Locale.US,it.balance)).append("\r\n")}}
    private fun csv(s:String)=if(s.contains(',')||s.contains('"')||s.contains('\n'))"\"${s.replace("\"","\"\"")}\"" else s
    private fun makePdf():PdfDocument{val p=PdfDocument();val page=p.startPage(PdfDocument.PageInfo.Builder(595,842,1).create());val c=page.canvas;val paint=Paint().apply{color=android.graphics.Color.BLACK;textSize=18f};c.drawText("MyExpenses - Account Ledger",40f,45f,paint);paint.textSize=10f;var y=75f;ledger().take(35).forEach{c.drawText("${it.date}  ${it.category}",40f,y,paint);c.drawText("${money(it.receive?:0.0)}  ${money(it.expense?:0.0)}  ${money(it.balance)}",310f,y,paint);y+=20};p.finishPage(page);return p}
    private fun printReport(){val list=filtered();val text=buildString{append("MyExpenses - Summary Report\n\n");append("Period: ${filterFrom?:"Start"} to ${filterTo?:"Today"}\n\n");list.groupBy{it.category}.forEach{(k,v)->append(k).append("  ").append(money(v.filter{it.type=="income"}.sumOf{it.amount})).append(" / ").append(money(v.filter{it.type=="expense"}.sumOf{it.amount})).append('\n')}};printText("Summary Report",text)}
    private fun printLedger(){val text=buildString{append("MyExpenses - Account Ledger\n\n");ledger().forEach{append("${it.date} | ${it.category} | ${money(it.receive?:0.0)} | ${money(it.expense?:0.0)} | ${money(it.balance)}\n")}};printText("Account Ledger",text)}
    private fun printText(title:String,text:String){val pm=getSystemService(PRINT_SERVICE) as PrintManager;pm.print(title,object:PrintDocumentAdapter(){override fun onLayout(old:PrintAttributes?,new:PrintAttributes?,cancellationSignal:CancellationSignal?,callback:LayoutResultCallback?,extras:Bundle?){callback?.onLayoutFinished(PrintDocumentInfo.Builder(title).setContentType(PrintDocumentInfo.CONTENT_TYPE_DOCUMENT).build(),true)};override fun onWrite(pages:Array<out PageRange>?,destination:ParcelFileDescriptor?,cancellationSignal:CancellationSignal?,callback:WriteResultCallback?){try{val pdf=PdfDocument();val page=pdf.startPage(PdfDocument.PageInfo.Builder(595,842,1).create());val paint=Paint().apply{color=android.graphics.Color.BLACK;textSize=11f};var y=40f;text.split('\n').forEach{line->page.canvas.drawText(line.take(100),30f,y,paint);y+=16;if(y>810f)return@forEach};pdf.finishPage(page);destination?.let{pdf.writeTo(it.fileDescriptor)};pdf.close();callback?.onWriteFinished(arrayOf(PageRange.ALL_PAGES))}catch(e:Exception){callback?.onWriteFailed(e.message)}}},null)}
    private fun exportSummary(){saveFile("summary")};private fun exportLedger(){saveFile("ledger")};private fun savePdf(){saveFile("pdf")}
}

@Composable fun MyExpensesApp(db:DB,prefs:android.content.SharedPreferences,save:(String)->Unit,restore:()->Unit,printReport:()->Unit,printLedger:()->Unit,exportSummary:()->Unit,exportLedger:()->Unit,savePdf:( )->Unit){
    var dark by remember{mutableStateOf(prefs.getBoolean("dark",false))};var tab by remember{mutableStateOf(0)};var refresh by remember{mutableIntStateOf(0)}
    val colors=if(dark)darkColorScheme() else lightColorScheme();MaterialTheme(colorScheme=colors){Scaffold(topBar={TopAppBar(title={Text("MyExpenses",fontWeight=FontWeight.ExtraBold)},actions={IconButton(onClick={dark=!dark;prefs.edit().putBoolean("dark",dark).apply()}){Icon(if(dark)Icons.Default.LightMode else Icons.Default.DarkMode,"Dark mode")}})},bottomBar={NavigationBar{listOf("Entry" to Icons.Default.Add,"History" to Icons.Default.Menu,"Report" to Icons.Default.Assessment).forEachIndexed{i,p->NavigationBarItem(selected=tab==i,onClick={tab=i},icon={Icon(p.second,p.first)},label={Text(p.first)})}}}){pad->Box(Modifier.padding(pad)){when(tab){0->EntryScreen(db,dark){refresh++};1->HistoryScreen(db){refresh++};2->ReportScreen(db,save,restore,printReport,printLedger,exportSummary,exportLedger,savePdf){refresh++}}}}}
}

