d);TextButton({manage=true}){Text("Manage Categories")}};OutlinedTextField(category,{category=it},modifier=Modifier.fillMaxWidth(),singleLine=true,placeholder={Text("Type or select category...")});Row(Modifier.horizontalScroll(rememberScrollState())){cats.forEach{c->AssistChip(onClick={category=c},label={Text(c)},modifier=Modifier.padding(end=6.dp))}};Button(onClick={val a=amount.toDoubleOrNull();if(category.isBlank()||a==null||a<=0)msg="Enter category and amount." else{db.insert(category.trim(),a,type,today,note.trim());if(!cats.contains(category.trim())){cats=cats+category.trim();saveCats(db,cats)};amount="";note="";category="";msg="Saved ✓";onChange()}},modifier=Modifier.fillMaxWidth()){Text("Save Entry")};Text(msg,modifier=Modifier.fillMaxWidth(),textAlign=androidx.compose.ui.text.style.TextAlign.Center,color=Color(0xFF16A34A),fontSize=12.sp)}}};item{Card{Column(Modifier.padding(14.dp)){Text("Today's Summary",fontWeight=FontWeight.Bold);if(carry!=0.0)Text("Carried Forward: ${money(carry)}",fontSize=12.sp,color=MaterialTheme.colorScheme.primary);Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(8.dp)){SummaryMini("Today Income",ti);SummaryMini("Today Expense",te);SummaryMini("Today Balance",ti-te)}}}}};if(calc)CalculatorDialog({amount=it;calc=false},{calc=false});if(manage)CategoryDialog(cats,{cats=it;saveCats(db,it)},{manage=false})}}

