@Composable private fun ReportScreen(db:DB,save:(String)->Unit,restore:()->Unit,printReport:()->Unit,printLedger:()->Unit,exportSummary:()->Unit,exportLedger:()->Unit,savePdf:()->Unit,onChange:()->Unit){var from by remember{mutableStateOf("")};var to by remember{mutableStateOf("")};var ledger by remember{mutableStateOf(false)};LaunchedEffect(from,to){(LocalContext.current as? MainActivity)?.let{it.filterFrom=from.ifBlank{null};it.filterTo=to.ifBlank{null}}};val rows=db.all(buildString{if(from.isNotBlank())append("date >= ? ");if(to.isNotBlank()){if(isNotEmpty())append("AND ");append("date <= ?")}},listOfNotNull(from.ifBlank{null},to.ifBlank{null}).toTypedArray(),"date ASC, created_at ASC");val inc=rows.filter{it.type=="income"}.sumOf{it.amount};val exp=rows.filter{it.type=="expense"}.sumOf{it.amount};val map=rows.groupBy{it.category};LazyColumn(Modifier.fillMaxSize().padding(14.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){item{Card{Column(Modifier.padding(14.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){Text("Report & Ledger",fontWeight=FontWeight.Bold);Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){OutlinedTextField(from,{from=it},label={Text("From")},modifier=Modifier.weight(1f),singleLine=true);OutlinedTextField(to,{to=it},label={Text("To")},modifier=Modifier.weight(1f),singleLine=true)};Row(horizontalArrangement=Arrangement.spacedBy(6.dp)){Button({ledger=false},{Text("Summary")});Button({ledger=true},{Text("Ledger")})};Row(horizontalArrangement=Arrangement.spacedBy(6.dp)){OutlinedButton({printReport()}){Text("Print")};OutlinedButton({exportSummary()}){Text("Excel")}};if(ledger)Row(horizontalArrangement=Arrangement.spacedBy(6.dp)){OutlinedButton({printLedger()}){Text("Print Ledger")};OutlinedButton({exportLedger()}){Text("CSV")};OutlinedButton({savePdf()}){Text("PDF")}}}}};if(!ledger){item{Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){SummaryMini("Income",inc);SummaryMini("Expense",exp);SummaryMini("Balance",inc-exp)}};item{Card{Column(Modifier.padding(14.dp)){Text("Particular-wise Summary",fontWeight=FontWeight.Bold);map.toList().sortedByDescending{it.second.sumOf{e->e.amount}}.forEach{(k,v)->val ex=v.filter{it.type=="expense"}.sumOf{it.amount};val inx=v.filter{it.type=="income"}.sumOf{it.amount};Column(Modifier.fillMaxWidth().padding(vertical=8.dp)){Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text(k,fontWeight=FontWeight.Bold);Text("${money(inx)} / ${money(ex)}")};if(exp>0&&ex>0)Text("${(ex/exp*100).round(2)}%",fontSize=11.sp,color=MaterialTheme.colorScheme.onSurfaceVariant)}}}}}}else{item{Card{Column(Modifier.padding(8.dp)){Text("Account Ledger",fontWeight=FontWeight.Bold);val m=if(from.isNotBlank())db.all("date < ?",arrayOf(from)).sumOf{if(it.type=="income")it.amount else -it.amount}else 0.0;var b=m;Row(Modifier.fillMaxWidth().padding(vertical=6.dp),horizontalArrangement=Arrangement.SpaceBetween){Text("Opening Balance");Text(money(b),fontWeight=FontWeight.Bold)};rows.forEach{e->if(e.type=="income")b+=e.amount else b-=e.amount;Row(Modifier.fillMaxWidth().padding(vertical=5.dp),horizontalArrangement=Arrangement.SpaceBetween){Column{Text(e.category,fontWeight=FontWeight.Bold);Text(e.date,fontSize=10.sp)};Text("${if(e.type=="income")"+" else "-"}${money(e.amount)}  ${money(b)}")}}}}}};item{Card{Column(Modifier.padding(14.dp)){Text("Backup & Restore",fontWeight=FontWeight.Bold);Text("Native Android file save/restore — no browser download required.",fontSize=12.sp);Button({save("backup")},Modifier.fillMaxWidth()){Text("Save Backup File")};OutlinedButton({restore()},Modifier.fillMaxWidth()){Text("Restore From File")}}}}}

@Composable private fun CalculatorDialog(set:(Double)->Unit,close:()->Unit){var exp by remember{mutableStateOf("")};AlertDialog(onDismissRequest=close,title={Text("Calculator")},text={Column{OutlinedTextField(exp,{exp=it},readOnly=true,modifier=Modifier.fillMaxWidth());val keys=listOf("7","8","9","/","4","5","6","*","1","2","3","-","0",".","C","+");Column{keys.chunked(4).forEach{row->Row(Modifier.fillMaxWidth()){row.forEach{k->Button({if(k=="C")exp="" else exp+=k},Modifier.weight(1f).padding(2.dp)){Text(k)}}}}}},confirmButton={Button({try{val r=eval(exp);set(r);close()}catch(_:Exception){exp=""}}){Text("Save to Amount")}},dismissButton={TextButton(close){Text("Close")}})}
private fun eval(s:String):Double{if(s.isBlank()||!s.matches(Regex("[0-9+\\-*/. ()]+")))throw Exception();val parts=Regex("(?<=[+\\-*/])|(?=[+\\-*/])").split(s).filter{it.isNotBlank()};var r=parts[0].toDouble();var i=1;while(i<parts.size){val op=parts[i];val n=parts[i+1].toDouble();r=when(op){"+"->r+n;"-"->r-n;"*"->r*n;"/"->r/n;else->throw Exception()};i+=2};return r}

@Composable private fun CategoryDialog(cats:List<String>,save:(List<String>)->Unit,close:()->Unit){var list by remember{mutableStateOf(cats)};var new by remember{mutableStateOf("")};AlertDialog(onDismissRequest=close,title={Text("Manage Categories")},text={Column{Row{OutlinedTextField(new,{new=it},modifier=Modifier.weight(1f),singleLine=true);Button({if(new.isNotBlank()){list=list+new.trim();new=""}},Modifier.padding(start=6.dp)){Text("Add")}};list.forEachIndexed{i,c->Row(Modifier.fillMaxWidth().padding(vertical=5.dp),horizontalArrangement=Arrangement.SpaceBetween){Text(c);TextButton({list=list.filterIndexed{ix,_->ix!=i}}){Text("Delete",color=Color.Red)}}}},confirmButton={Button({save(list);close()}){Text("Done")}})}

@Composable private fun EditDialog(e:Entry,save:(Entry)->Unit,close:()->Unit){var cat by remember{mutableStateOf(e.category)};var amt by remember{mutableStateOf(e.amount.toString())};var type by remember{mutableStateOf(e.type)};var date by remember{mutableStateOf(e.date)};var note by remember{mutableStateOf(e.note)};AlertDialog(onDismissRequest=close,title={Text("Edit Entry")},text={Column(verticalArrangement=Arrangement.spacedBy(8.dp)){Row{FilterChip(type=="income",{type="income"},label={Text("Income")});FilterChip(type=="expense",{type="expense"},label={Text("Expense")})};OutlinedTextField(cat,{cat=it},label={Text("Category")});OutlinedTextField(note,{note=it},label={Text("Note")});OutlinedTextField(amt,{amt=it},label={Text("Amount")},keyboardOptions=KeyboardOptions(keyboardType=KeyboardType.Decimal));OutlinedTextField(date,{date=it},label={Text("Date")},singleLine=true)}},confirmButton={Button({amt.toDoubleOrNull()?.let{save(e.copy(category=cat,amount=it,type=type,date=date,note=note));close()}}){Text("Update")}},dismissButton={TextButton(close){Text("Cancel")}})}

private fun loadCats(db:DB):List<String>{val saved=db.categories();return if(saved.isEmpty()) listOf("Salary","Food","Transport","Shopping","Bills","Health","Entertainment","Investment","Others") else saved}
private fun saveCats(db:DB,c:List<String>){db.saveCategories(c)}
private fun today()=SimpleDateFormat("yyyy-MM-dd",Locale.US).format(Date())
private fun money(v:Double)="৳"+String.format(Locale.US,"%,.2f",v)
private fun Double.round(n:Int)=String.format(Locale.US,"%.${n}f",this).toDouble()
